import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const EcraDivididoDiagonal: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const t = useCurrentFrame();
  const params = (anim.params ?? {}) as Record<string, unknown>;
  // `src` is the pipeline's slot; src2 (or a srcs array) carries the second image.
  const list = Array.isArray(params.srcs) ? (params.srcs as unknown[]) : [];
  const srcTop = String(params.src ?? list[0] ?? "");
  const srcBottom = String(params.src2 ?? list[1] ?? srcTop);

  const num = (v: unknown, def: number, min: number, max: number) => {
    const n = Number(v);
    return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : def;
  };
  const angle = num(params.angle, 7, 0, 25);
  const entrySeconds = num(params.entrySeconds, 0.5, 0.1, 3);

  const W = frame.width;
  const H = frame.height;
  const total = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const entryEnd = Math.max(1, Math.min(total - 1, Math.round(entrySeconds * fps)));

  // The seam rises from left to right; its tilt never takes more than 30% of the height.
  const tilt = Math.min(W * Math.tan((angle * Math.PI) / 180), H * 0.3);
  const yL = H / 2 + tilt / 2;
  const yR = H / 2 - tilt / 2;
  const gap = Math.max(4, Math.round(Math.min(W, H) * 0.01));
  const drift = W * 0.06;

  // Fast entry, then a slow constant drift in the same direction for the rest of the layer.
  const entry = interpolate(t, [0, entryEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const pan = interpolate(t, [0, total], [0, drift], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const line = interpolate(t, [entryEnd * 0.6, entryEnd + fps * 0.3], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  const half = (top: boolean) => {
    const src = top ? srcTop : srcBottom;
    const clip = top
      ? `polygon(0px 0px, ${W}px 0px, ${W}px ${yR - gap / 2}px, 0px ${yL - gap / 2}px)`
      : `polygon(0px ${yL + gap / 2}px, ${W}px ${yR + gap / 2}px, ${W}px ${H}px, 0px ${H}px)`;
    // Each image covers its own band (the widest point of it), so the subject stays in view.
    const bandTop = top ? 0 : yR;
    const bandH = top ? yL : H - yR;
    const x = top ? -(1 - entry) * (W + drift) + pan : (1 - entry) * (W + drift) - pan;

    return (
      <AbsoluteFill style={{ clipPath: clip }}>
        <div
          style={{
            position: "absolute",
            top: bandTop,
            height: bandH,
            left: top ? -drift : 0,
            width: W + drift,
            translate: `${x}px 0px`,
            backgroundColor: src ? undefined : "rgba(255,255,255,0.06)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {src ? (
            <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          ) : (
            <div
              style={{
                color: muted,
                fontFamily: FONTS.body,
                fontWeight: FONTS.bodyWeight,
                fontSize: Math.round(Math.min(W, bandH) * 0.06),
                letterSpacing: "0.12em",
                textTransform: "uppercase",
                textAlign: "center",
                padding: "0 5%",
              }}
            >
              Sem imagem
            </div>
          )}
        </div>
      </AbsoluteFill>
    );
  };

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {half(true)}
      {half(false)}
      <svg width={W} height={H} style={{ position: "absolute", inset: 0 }}>
        <line
          x1={0}
          y1={yL}
          x2={W * line}
          y2={yL + (yR - yL) * line}
          stroke={COLORS.teal}
          strokeWidth={Math.max(2, gap * 0.6)}
          strokeLinecap="round"
          opacity={line > 0 ? 1 : 0}
        />
      </svg>
    </AbsoluteFill>
  );
};

export default EcraDivididoDiagonal;

