import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const EcraDivididoDeslize: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const t = useCurrentFrame();
  const src = String(anim.params?.src ?? "");
  const entryRaw = Number(anim.params?.entrySeconds);
  const driftRaw = Number(anim.params?.drift);
  const entrySeconds = Number.isFinite(entryRaw) && entryRaw > 0 ? entryRaw : 0.45;
  const drift = Number.isFinite(driftRaw) && driftRaw >= 0 ? Math.min(driftRaw, 30) : 12;

  const total = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const entryEnd = Math.max(1, Math.min(total - 1, Math.round(entrySeconds * fps)));
  const gap = Math.max(4, Math.round(frame.height * 0.008));
  const panelH = (frame.height - gap) / 2;

  // Fast entry: 0 = fully off-screen, 1 = in place.
  const entry = interpolate(t, [0, entryEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  // Slow pan across the whole layer, in the same direction as the entry.
  const pan = interpolate(t, [0, total], [0, drift], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  const panel = (fromLeft: boolean, top: number) => (
    <div
      style={{
        position: "absolute",
        left: 0,
        top,
        width: frame.width,
        height: panelH,
        overflow: "hidden",
        translate: `${(fromLeft ? -1 : 1) * (1 - entry) * frame.width}px 0px`,
        backgroundColor: src ? undefined : "rgba(255,255,255,0.06)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {src ? (
        <Img
          src={src}
          style={{
            position: "absolute",
            top: 0,
            height: "100%",
            width: `${100 + drift}%`,
            left: `${fromLeft ? pan - drift : -pan}%`,
            objectFit: "cover",
          }}
        />
      ) : (
        <div
          style={{
            color: muted,
            fontFamily: FONTS.body,
            fontWeight: FONTS.bodyWeight,
            fontSize: Math.round(Math.min(frame.width, panelH) * 0.08),
            letterSpacing: "0.12em",
            textTransform: "uppercase",
            textAlign: "center",
            padding: "0 5%",
          }}
        >
          Sem imagem
        </div>
      )}
    </div>
  );

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {panel(true, 0)}
      {panel(false, panelH + gap)}
    </AbsoluteFill>
  );
};

export default EcraDivididoDeslize;
